INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(11201, '2 Chronicles 35:8', '2 Chronicles', 35, 8, '&nbsp;د هغۀ آفسرانو په خپله خوښه خلقو، اِمامانو او د ليويانو د استعمال دپاره هم ځناور ورکړل. او د مالِک خُدائ د کور مشرانو آفسرانو، مشر اِمام خِلقياه، زکرياه او يحى‌ايل اِمامانو له دوه زره او شپږ سوه ګډُورى او د چېلو بچى او درې سوه غوَيى ورکړل چې په اختر کښې قربانى شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11202, '2 Chronicles 35:9', '2 Chronicles', 35, 9, '&nbsp;د ليويانو مشرانو، کنعنياه، او د هغۀ وروڼه سمعياه او نتنى‌ايل، او ورسره حسبياه، يعى‌ايل او يوزبد پينځۀ زره ګډُورى او د چېلو بچى او پينځۀ سوه غوَيى ليويانو له ورکړل چې د فسحې په اختر کښې يې قربانى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11203, '2 Chronicles 35:10', '2 Chronicles', 35, 10, '&nbsp;کله چې د فسحې اختر دپاره هر څۀ تيار شول، نو اِمامان او ليويان د بادشاه د حُکم په مطابق په خپلو ځايونو ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11204, '2 Chronicles 35:11', '2 Chronicles', 35, 11, '&nbsp;کله چې ګډُورى او چېلى حلال کړے شول، نو اِمامانو په قربان‌ګاه باندې وينه وشيندله او ليويانو د هغې نه څرمنې وويستلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11205, '2 Chronicles 35:12', '2 Chronicles', 35, 12, '&nbsp;بيا هغوئ څاروى د سوزېدونکې نذرانې دپاره د کورَنو د ډلو په مطابق په خلقو باندې تقسيم کړل، نو هغوئ دا د موسىٰ د شريعت د اصُولو په مطابق پېش کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11206, '2 Chronicles 35:13', '2 Chronicles', 35, 13, '&nbsp;ليويانو د اصُولو په مطابق د فسحې اختر قربانۍ په اور وريتې کړې او مقدسې نذرانې يې په لوښو کښې، دېګونو او پَتيلو کښې ويشولې او غوښه يې زر زر په خلقو باندې تقسيم کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11207, '2 Chronicles 35:14', '2 Chronicles', 35, 14, '&nbsp;د دې کېدو نه پس، ليويانو د خپل ځان دپاره او د هارون د اولاد اِمامانو دپاره د غوښې بندوبست وکړو، ځکه چې اِمامان د سحر نه واخله تر ماښام پورې مصروف وُو او د قربانو وازګه او هغه څاروى يې سوزول چې په پوره توګه سوزولے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11208, '2 Chronicles 35:15', '2 Chronicles', 35, 15, '&nbsp;د ليوى قبيلې د آسف د قبيلې دا موسيقاران په هغه ځايونو کښې وُو کوم چې هغوئ ته د داؤد د اصُولو په مطابق حواله شوى وُو، آسف، هيمان او د بادشاه پېغمبر يدوتون. د مالِک خُدائ د کور د دروازو څوکيدارانو ته د خپلو ځايونو نه د تلو ضرورت نۀ وو، ځکه چې نورو ليويانو د هغوئ دپاره د فسحې اختر تيار کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11209, '2 Chronicles 35:16', '2 Chronicles', 35, 16, '&nbsp;څنګه چې يوسياه بادشاه حُکم کړے وو نو په هغه ورځ د مالِک خُدائ د عبادت دپاره او د فسحې اختر کولو دپاره او په قربان‌ګاه باندې د سوزېدونکې نذرانې سوزولو دپاره هر څۀ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11210, '2 Chronicles 35:17', '2 Chronicles', 35, 17, '&nbsp;کوم بنى اِسرائيليان چې موجود وُو نو هغه ټولو اووۀ ورځې د فسحې اختر او د پتيرې روټۍ اختر وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11211, '2 Chronicles 35:18', '2 Chronicles', 35, 18, '&nbsp;د سموئيل پېغمبر د وخت نه د فسحې اختر دغه شان نۀ وو شوے. په پخوانو بادشاهانو کښې يو کس کله هم د فسحې داسې اختر نۀ وو کړے، چې کوم يوسياه بادشاه، اِمامانو، ليويانو او د يهوداه، اِسرائيل او د يروشلم خلقو وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11212, '2 Chronicles 35:19', '2 Chronicles', 35, 19, '&nbsp;د يوسياه د بادشاهۍ په اتلسم کال داسې وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11213, '2 Chronicles 35:20', '2 Chronicles', 35, 20, '&nbsp;کله چې يوسياه بادشاه د مالِک خُدائ کور دپاره دا هر څۀ وکړل، نو د مِصر بادشاه نِکوه يو لښکر روان کړو چې د فرات په سيند په کرکميس کښې جنګ وکړى. او يوسياه د هغۀ خِلاف د جنګ کولو دپاره راووتلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11214, '2 Chronicles 35:21', '2 Chronicles', 35, 21, '&nbsp;خو نِکوه يوسياه له دا پېغام ولېږلو، ”د يهوداه بادشاه دا جنګ چې زۀ کوم د دې تعلق تا سره نشته. زۀ تا سره جنګ کولو دپاره نۀ يم راغلے، زۀ د خپلو دشمنانو سره د جنګ کولو دپاره راغلے يم او خُدائ پاک راته فرمائيلى دى چې تېز لاړ شه. خُدائ پاک زما مل دے، نو زما مخالفت مۀ کوه، ګنې هغه به تا تباه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11215, '2 Chronicles 35:22', '2 Chronicles', 35, 22, '&nbsp;خو خُدائ پاک چې د نِکوه فِرعون په ذريعه څۀ وفرمائيل نو يوسياه هغې ته غوږ نۀ کېښودو، نو هغۀ خپل شکل بدل کړو او د مِجدو په مېدان کښې د جنګ دپاره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11216, '2 Chronicles 35:23', '2 Chronicles', 35, 23, '&nbsp;د جنګ په دوران کښې يوسياه بادشاه د مِصريانو په غشو باندې ولګېدو. هغۀ خپلو نوکرانو له حُکم ورکړو، ”ما د دې ځائ نه بوځئ، زۀ سخت زخمى شوے يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11217, '2 Chronicles 35:24', '2 Chronicles', 35, 24, '&nbsp;هغوئ هغه د خپل جنګى ګاډۍ نه اوچت کړو او چې هلته د هغۀ کومه دوېمه جنګى ګاډۍ وه په هغې کښې يې واچولو او يروشلم ته يې يوړو. هلته هغه مړ شو او په شاهى اديره کښې ښخ کړے شو. د يهوداه او يروشلم ټولو خلقو د هغۀ په مرګ باندې د غم ژړا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11218, '2 Chronicles 35:25', '2 Chronicles', 35, 25, '&nbsp;يرمياه پېغمبر د يوسياه بادشاه دپاره يوه د غم سندره جوړه کړه. نو د اِسرائيل په مُلک کښې د سندرغاړو، ناريناؤ او زناناؤ دواړو دا يو رِواج جوړ شو، چې کله به هغوئ د هغۀ دپاره د غم ژړا کوله نو دا سندره به يې وئيله. دا سندره د مرثيو په کِتاب کښې ليکلے شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11219, '2 Chronicles 35:26', '2 Chronicles', 35, 26, '&nbsp;يوسياه چې نور هر څۀ هم کړى وُو، مالِک خُدائ ته د هغۀ وقف کېدل، د هغۀ د شريعت تابعدارى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11220, '2 Chronicles 35:27', '2 Chronicles', 35, 27, '&nbsp;او د اول نه واخله تر آخره پورې د هغۀ تاريخ دا هر څۀ د اِسرائيل او يهوداه په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11221, '2 Chronicles 36:1', '2 Chronicles', 36, 1, '&nbsp;د يهوداه خلقو د يوسياه زوئ يهوآخز خوښ کړو او په يروشلم کښې يې بادشاه جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11222, '2 Chronicles 36:2', '2 Chronicles', 36, 2, '&nbsp;يهوآخز د درويشتو کالو وو چې هغه د يهوداه بادشاه شو او درې مياشتې يې په يروشلم بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11223, '2 Chronicles 36:3', '2 Chronicles', 36, 3, '&nbsp;د مِصر بادشاه نِکوه هغه قېدى کړو او د يهوداه خلق يې دې ته مجبور کړل چې درې زره او څلور سوه کلو سپين زر او څلور دېرش کلو سرۀ زر محصُول ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11224, '2 Chronicles 36:4', '2 Chronicles', 36, 4, '&nbsp;نِکوه اِلياقيم د يهوداه بادشاه جوړ کړو چې هغه د يهوآخز ورور وو او د هغۀ نوم يې يهويقيم ته بدل کړو. نِکوه يهوآخز مِصر ته بوتلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11225, '2 Chronicles 36:5', '2 Chronicles', 36, 5, '&nbsp;يهويقيم د پينځويشتو کالو وو چې هغه د يهوداه بادشاه شو او هغۀ په يروشلم باندې يوولس کاله بادشاهى وکړه. هغۀ د مالِک خُدائ خپل خُدائ پاک خِلاف ګناه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11226, '2 Chronicles 36:6', '2 Chronicles', 36, 6, '&nbsp;د بابل بادشاه نبوکدنضر په يهوداه حمله وکړه، يهويقيم يې ونيولو او بابل ته يې په زنځيرونو کښې بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11227, '2 Chronicles 36:7', '2 Chronicles', 36, 7, '&nbsp;نبوکدنضر د مالِک خُدائ د کور څۀ خزانې يوړې او په بابل کښې يې په خپل محل کښې کېښودې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11228, '2 Chronicles 36:8', '2 Chronicles', 36, 8, '&nbsp;يهويقيم چې هر څۀ هم کړى وُو، سره د هغۀ د خرابو رسمونو او چې هغۀ کوم حرام کارونه کړى وُو، هغه د اِسرائيل او د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى. نو د هغۀ زوئ يهوياکين د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11229, '2 Chronicles 36:9', '2 Chronicles', 36, 9, '&nbsp;يهوياکين د اتلسو کالو وو چې هغه د يهوداه بادشاه شو او هغۀ په يروشلم درې مياشتې او لس ورځې بادشاهى وکړه. هغۀ هم د مالِک خُدائ خِلاف ګناه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11230, '2 Chronicles 36:10', '2 Chronicles', 36, 10, '&nbsp;کله چې سپرلے شو، نو نبوکدنضر بادشاه يهوياکين بابل ته قېدى بوتلو او د مالِک خُدائ د کور خزانې يې يوړې. بيا نبوکدنضر د يهوياکين ترۀ صدقياه د يهوداه او يروشلم بادشاه جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11231, '2 Chronicles 36:11', '2 Chronicles', 36, 11, '&nbsp;صدقياه د يوويشتو کالو وو چې هغه د يهوداه بادشاه شو او په يروشلم يې يوولس کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11232, '2 Chronicles 36:12', '2 Chronicles', 36, 12, '&nbsp;هغۀ د مالِک خُدائ خِلاف ګناه وکړه او د يرمياه پېغمبر خبرې يې په عاجزۍ سره وانۀ ورېدلې، چا چې د مالِک خُدائ خبرې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11233, '2 Chronicles 36:13', '2 Chronicles', 36, 13, '&nbsp;صدقياه د نبوکدنضر بادشاه خِلاف بغاوت وکړو، اګر چې هغۀ د خُدائ پاک په وړاندې دا لوظ کړے وو چې د نبوکدنضر وفادار به وى. هغه د خپل ضد په وجه نۀ توبه ګار کېدو او مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک يې څۀ پرواه نۀ ساتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11234, '2 Chronicles 36:14', '2 Chronicles', 36, 14, '&nbsp;د دې نه علاوه، د يهوداه لار ښوونکى اِمامان او خلق د بُتانو په عبادت کښې د هغوئ نه ګېرچاپېره ګناهګارو قومونو په نقش قدم باندې روان وُو او د هغوئ په شان حرام کارونه يې وکړل، هغوئ د مالِک خُدائ هغه کور ناپاک کړو کوم چې مالِک خُدائ په خپله مقدس کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11235, '2 Chronicles 36:15', '2 Chronicles', 36, 15, '&nbsp;مالِک خُدائ د هغوئ د پلار نيکۀ خُدائ پاک د خپلو خلقو د خبردارى دپاره پېغمبران رالېږل، ځکه چې خُدائ پاک غوښتل چې هغوئ او خپل کور بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11236, '2 Chronicles 36:16', '2 Chronicles', 36, 16, '&nbsp;خو هغوئ د خُدائ پاک په پېغام وړونکو پورې ټوقې وکړې، د هغوئ خبرو ته يې توجو ورنۀ کړه او د هغۀ په پېغمبرانو پورې يې خندا وکړه، تر دې پورې چې د مالِک خُدائ غصه د هغۀ د خلقو خِلاف دومره زياته شوه چې د هغې نه د خلاصون لار نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11237, '2 Chronicles 36:17', '2 Chronicles', 36, 17, '&nbsp;نو مالِک خُدائ د بابل بادشاه راوستو چې په هغوئ حمله وکړى، تر دې چې د مالِک خُدائ په کور کښې هم هغۀ د يهوداه زلمى ووژل. هغۀ په ځوان يا بوډا، په نر يا ښځه، بيمار يا روغ په هيچا هم رحم نۀ کولو. خُدائ پاک هغوئ ټول ورته حواله کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11238, '2 Chronicles 36:18', '2 Chronicles', 36, 18, '&nbsp;د بابل بادشاه د مالِک خُدائ کور، د دې خزانې او د بادشاه او د هغۀ د آفسرانو دولت لوټ کړو او هر څۀ يې بابل ته يوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11239, '2 Chronicles 36:19', '2 Chronicles', 36, 19, '&nbsp;هغۀ د مالِک خُدائ کور او ښار، سره د دې ټولو محلونو او دولت وسوزولو او د ښار دېوال يې راوغورزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11240, '2 Chronicles 36:20', '2 Chronicles', 36, 20, '&nbsp;هغۀ ټول ژوندى پاتې کسان بابل ته بوتلل، چرته چې هغوئ او د هغوئ اولاد تر هغې پورې د نوکرانو په توګه د هغۀ خِدمت کولو چې د فارس حکومت را اوچت شوے نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11241, '2 Chronicles 36:21', '2 Chronicles', 36, 21, '&nbsp;د يرمياه پېغمبر په ذريعه چې د مالِک خُدائ کوم پېغام اورولے شوے وو نو هغه پوره شو چې، ”اويا کاله به هغه زمکه شاړه پرته وى، ځکه چې هغې د سبت آرام نۀ وو کړے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11242, '2 Chronicles 36:22', '2 Chronicles', 36, 22, '&nbsp;د فارس د خورس بادشاه د بادشاهۍ په وړومبى کال مالِک خُدائ هغه څۀ رښتيا کړل چې څۀ يې د يرمياه پېغمبر په ذريعه فرمائيلى وُو. هغۀ د خورس حوصله افزائى وکړه چې دا حُکم جارى کړى او د خط په شکل کښې د هغۀ د بادشاهۍ هر ځائ ته ولېږلے شى او بيان شى:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11243, '2 Chronicles 36:23', '2 Chronicles', 36, 23, '&nbsp;”دا د فارس د خورس بادشاه حُکم دے. مالِک خُدائ، د آسمان خُدائ پاک زۀ په ټوله دُنيا باندې حکمران جوړ کړے يم او ما له يې دا ذمه وارى راکړې ده چې د هغۀ دپاره د يروشلم په يهوداه کښې يو کور جوړ کړم، نو تاسو ټول څوک چې د خُدائ پاک خلق يئ، هلته ځئ او مالِک خُدائ ستاسو خُدائ پاک دې ستاسو مل شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11244, 'Ezra 1:1', 'Ezra', 1, 1, '&nbsp;په وړومبى کال کښې چې خورس د فارس بادشاه وو، نو مالِک خُدائ هغه پېشګوئې پوره کړه چې هغۀ د يرمياه په ذريعه کړې وه. هغۀ د خورس په زړۀ کښې دا خبره واچوله چې دا فرمان وليکى او جارى يې کړى او خپلې ټولې بادشاهۍ ته يې ولېږى:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11245, 'Ezra 1:2', 'Ezra', 1, 2, '&nbsp;”دا د فارس د بادشاه خورس حُکم دے. مالِک خُدائ، د آسمانونو خُدائ پاک زۀ په ټوله دُنيا باندې حکمران کړے يم او دا ذمه وارى يې راکړې ده چې د مالِک خُدائ دپاره په يهوداه کښې د يروشلم په ښار کښې کور جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11246, 'Ezra 1:3', 'Ezra', 1, 3, '&nbsp;هر څوک چې د هغۀ خلق وى نو هغه د يهوداه يروشلم ته تلے شئ چې د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک دپاره يو کور بيا جوړ کړئ، د چا عبادت چې په يروشلم کښې کيږى. او ستاسو خُدائ پاک دې ستاسو مل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11247, 'Ezra 1:4', 'Ezra', 1, 4, '&nbsp;ژوندى پاتې شوى خلق چې چرته هم اوسيږى، نو خپل ګاونډيان به ورله په مدد کښې دا څيزونه ورکړى لکه چې سپين زر، سرۀ زر، د سفر دپاره توښه، د سورلۍ ځناور او داسې نذرانې هم چې په يروشلم کښې د خُدائ پاک په کور کښې پېش کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11248, 'Ezra 1:5', 'Ezra', 1, 5, '&nbsp;بيا د يهوداه او د بنيامين قبيلو د ډلو مشران، اِمامان او ليويان او هغه نور ټول تيار شول چې خُدائ پاک د هغوئ زړونه راپاڅولى وُو او په يروشلم کښې د مالِک خُدائ د کور د بيا جوړولو دپاره لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11249, 'Ezra 1:6', 'Ezra', 1, 6, '&nbsp;د هغوئ ټولو ګاونډيانو د هغوئ مدد وکړو او هغوئ له يې د سپينو زرو څيزونه، سرۀ زر، د سفر دپاره توښه، د سورلۍ دپاره ځناور او قيمتى څيزونه ورکړل، د دې هر څۀ نه علاوه رضاکارانه نذرانې يې هم ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11250, 'Ezra 1:7', 'Ezra', 1, 7, '&nbsp;خورس بادشاه هغوئ له هغه جامونه او پيالۍ واپس ورکړې چې کومې نبوکدنضر بادشاه په يروشلم کښې د مالِک خُدائ د کور نه اوړې وې او د خپلو بُتانو په کور کښې يې اېښې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11251, 'Ezra 1:8', 'Ezra', 1, 8, '&nbsp;د فارس بادشاه خورس دا د شاهى خزانې مشر مِتردات ته حواله کړل، مِتردات د دې نه يو فهرست جوړ کړو او د يهوداه مشر شيسبضر له ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11252, 'Ezra 1:11', 'Ezra', 1, 11, '&nbsp;هلته ټول پينځۀ زره او څلور سوه د سرو زرو او سپينو زرو لوښى وُو او هغه نور سامان وو کوم چې شيسبضر په هغه وخت کښې د ځان سره وړے وو چې کله هغه او نور جلاوطن شوى کسان د بابل نه يروشلم ته تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11253, 'Ezra 2:1', 'Ezra', 2, 1, '&nbsp;دا د يهوديانو د جلاوطن شوو خلقو تفصيل دے څوک چې د آزادېدو نه پس واپس خپلو صُوبو ته تلل. نبوکدنضر بادشاه هغوئ بابل ته قېديان بوتلى وُو، خو اوس يروشلم، يهوداه او خپلو نورو ښارونو ته راواپس شول چرته چې هغوئ مخکښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11254, 'Ezra 2:2', 'Ezra', 2, 2, '&nbsp;د هغوئ مشران زرُبابل، يشوَع، نحمياه، شراياه، رعلاياه، مردکى، بِلشان، مِسفار، بِګوئ، رحُوم او بعنه وُو. دا د بنى اِسرائيلو د ډلو تفصيل دے، دا تفصيل د هغه هرې قبيلې د شمېر سره دے کوم چې د جلاوطنۍ نه راواپس شوى وُو:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11255, 'Ezra 2:58', 'Ezra', 2, 58, '&nbsp;د مالِک خُدائ د کور د خِدمتګارانو د اولاد او د سليمان د نوکرانو د اولاد ټول شمېر اتۀ کم څلور سوه وو کوم چې د جلاوطنۍ نه راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11256, 'Ezra 2:63', 'Ezra', 2, 63, '&nbsp;د يهوداه حکمران ورته وئيلى وُو چې هغوئ تر هغه وخته پورې خُدائ پاک ته پېش کړے شوے خوراک نۀ شى خوړلے چې ترڅو يو داسې اِمام نۀ وى چې هغه اُوريم او تميم نه کار واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11257, 'Ezra 2:68', 'Ezra', 2, 68, '&nbsp;کله چې جلاوطن شوى کسان په يروشلم کښې د مالِک خُدائ کور ته راورسېدل، نو د ډلو څۀ مشرانو رضاکارانه نذرانې د دې دپاره ورکړې چې د مالِک خُدائ کور په خپل زوړ ځائ کښې بيا جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11258, 'Ezra 2:69', 'Ezra', 2, 69, '&nbsp;هغوئ چې د دې کار دپاره څومره نذرانې ورکولے شوې نو هغه هومره يې ورکړې او ټول پينځۀ سوه کلو سرۀ زر، دوه زره او اتۀ سوه کلو سپين زر او د اِمامانو دپاره سل چُوغې ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11259, 'Ezra 2:70', 'Ezra', 2, 70, '&nbsp;اِمامان، ليويان او څۀ خلق په يروشلم کښې يا د دې سره نزدې دېره شول، موسيقاران، د مالِک خُدائ د کور څوکيداران او د مالِک خُدائ د کور خِدمتګاران په نزدې ښارونو کښې دېره شول، او باقى نور بنى اِسرائيليان په هغه ښارونو کښې دېره شول چرته چې د هغوئ پلار نيکۀ اوسېدلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11260, 'Ezra 3:1', 'Ezra', 3, 1, '&nbsp;په اوومه مياشت کښې ټول بنى اِسرائيل په خپلو خپلو ښارونو کښې دېره شول. بيا هغوئ ټول په يروشلم کښې په اتفاق سره راغونډ شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11261, 'Ezra 3:2', 'Ezra', 3, 2, '&nbsp;او د يوصدق زوئ يشوَع، د هغۀ ملګرو اِمامانو او د شلتى‌اېل زوئ زرُبابل سره د خپلو رشته‌دارانو، د بنى اِسرائيلو د خُدائ پاک قربان‌ګاه بيا جوړه کړه، نو چې هغوئ په دې باندې د هغه اصُولو په مطابق قربانۍ وسوزوى کوم چې د موسىٰ په شريعت کښې ليکلے شوى وُو، موسىٰ د خُدائ پاک خِدمتګار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11262, 'Ezra 3:3', 'Ezra', 3, 3, '&nbsp;اګر چې د جلاوطنۍ نه واپس راتلونکى کسان بيا هم د هغه خلقو نه يرېدل کوم چې په هغه مُلک کښې اوسېدل، هغوئ قربان‌ګاه په هغه ځائ کښې بيا جوړه کړه چرته چې مخکښې ولاړه وه. بيا هغوئ يو ځل بيا په هغې باندې د هر سحر او هر ماښام نذرانې سوزول شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11263, 'Ezra 3:4', 'Ezra', 3, 4, '&nbsp;هغوئ د اصُولو په مطابق د جونګړو اختر وکړو، هغوئ هره ورځ د هغه ورځې مقررې قربانۍ پېش کولې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11264, 'Ezra 3:5', 'Ezra', 3, 5, '&nbsp;او د دې نه علاوه هغوئ د هرې ورځې سوزېدونکې نذرانې هم پېش کولې او هغه نذرانې يې هم پېش کولې چې د نوې مياشتې په اختر او په کلنى اخترونو کښې پېش کېدلې چې په دې اخترونو کښې به د مالِک خُدائ عبادت کېدلو، او هم داسې هغه ټولې نذرانې هم پېش کېدلې کومې چې مالِک خُدائ ته په رضاکارانه توګه ورکولے شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11265, 'Ezra 3:6', 'Ezra', 3, 6, '&nbsp;اګر چې خلقو تر اوسه پورې د مالِک خُدائ د کور بنياد جوړول هم شروع کړى نۀ وُو، خو هغوئ د اوومې مياشتې په اوله ورځ مالِک خُدائ ته قربانۍ سوزول شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11266, 'Ezra 3:7', 'Ezra', 3, 7, '&nbsp;خلقو د کاڼو ګِلکارانو او ترکاڼانو د مزدورۍ دپاره پېسې ورکولې او خوراک، څښاک او د زيتُونو تېل يې د صور او صيدا خلقو له لېږل او د دې څيزونو په بدل کښې د لبنان د غرونو نه د دِيار لرګى د يافا ښار ته د سمندر په ذريعه راوړلے کېدل. دا هر څۀ د فارس د بادشاه خورس په اجازت سره کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11267, 'Ezra 3:8', 'Ezra', 3, 8, '&nbsp;د هغې نه پس چې هغوئ په يروشلم کښې د مالِک خُدائ د کور ځائ ته واپس راغلى وُو نو د هغه کال په دوېمه مياشت يې کار شروع کړو. زرُبابل، يشوَع او د هغۀ نور وطنداران، اِمامان او ليويان او هغه ټول خلق په کار کښې شامل شول کوم چې د جلاوطنۍ نه يروشلم ته واپس راغلى وُو. هغه ټول ليويان چې د هغوئ عُمر شل کاله يا د دې نه زيات وو هغوئ د مالِک خُدائ د کور د بيا جوړېدو مشران مقرر شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11268, 'Ezra 3:9', 'Ezra', 3, 9, '&nbsp;ليوى يشوَع او د هغۀ زامنو او خپلوانو او د هُوداوياه د قبيلې قدمى‌اېل او د هغۀ زامنو د مالِک خُدائ د کور په بيا جوړېدو کښې په شريکه مشرى کوله. د هغوئ مدد د حنداد د قبيلې ليويانو هم کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11269, 'Ezra 3:10', 'Ezra', 3, 10, '&nbsp;کله چې ګِلکارانو د مالِک خُدائ د کور بنياد کېښودل شروع کړل، نو اِمامان په خپلو ځايونو باندې ولاړ وُو، چُوغې يې اغوستې وې او بيګل د هغوئ په لاسونو کښې وُو او د آسف د قبېلې ليويان د چمټو سره هلته ولاړ وُو. هغوئ د مالِک خُدائ ثناء صِفت د هغه اصُولو په مطابق کولو کوم اصُول چې داؤد بادشاه ښودلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11270, 'Ezra 3:11', 'Ezra', 3, 11, '&nbsp;هغوئ وار په وار د مالِک خُدائ ثناء صِفت کولو، ”مالِک خُدائ مهربان دے او د بنى اِسرائيلو سره د هغۀ مينه د همېشه دپاره ده.“ هر چا به په اوچت آواز سره د مالِک خُدائ ثناء صِفت کولو، ځکه چې د مالِک خُدائ د کور د بنياد کار شروع شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11271, 'Ezra 3:12', 'Ezra', 3, 12, '&nbsp;چې کله د مالِک خُدائ د دې کور بنياد کېښودے شو نو کومو ډېرو بوډاګانو اِمامانو، ليويانو او د ډلو مشرانو چې د مالِک خُدائ هغه وړومبے کور ليدلے وو، نو په چغو يې وژړل. خو چې هلته نور کوم خلق وُو هغوئ د خوشحالۍ نه چغې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11272, 'Ezra 3:13', 'Ezra', 3, 13, '&nbsp;څۀ خلقو د خوشحالۍ نه چغې وهلې او څۀ خلقو ژړا کوله، او هغوئ دومره شور کولو چې تر لرې لرې پورې اورېدلے شو او هيچا ته پته نۀ لګېده چې څوک ژاړى او څوک خوشحاله دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11273, 'Ezra 4:1', 'Ezra', 4, 1, '&nbsp;د يهوداه او بنيامين د خلقو دشمنان د دې نه خبر شول چې کوم خلق د جلاوطنۍ نه راواپس شوى دى نو هغوئ د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک کور بيا جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11274, 'Ezra 4:2', 'Ezra', 4, 2, '&nbsp;نو هغوئ د زرُبابل او د ډلو مشرانو سره مِلاوېدو له راغلل او ورته يې ووئيل، ”د مالِک خُدائ په کور جوړولو کښې به مونږ هم درسره ملګرى شُو. مونږ هم د هغه خُدائ پاک عبادت کوُو د کوم چې تاسو کوئ، مونږ هغۀ ته قربانۍ پېش کوُو د اسور بادشاه اسرحدون د وخت نه چا چې مونږ دلته د اوسېدو دپاره راولېږلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11275, 'Ezra 4:3', 'Ezra', 4, 3, '&nbsp;نو زرُبابل، يشوَع او د ډلو مشرانو هغوئ ته ووئيل، ”مونږ ته د مالِک خُدائ زمونږ د خُدائ پاک په کور جوړولو کښې ستاسو د مدد هيڅ ضرورت نشته. مونږ به دا په خپله جوړوُو هم هغه شان چې څنګه د فارس بادشاه خورس حُکم راکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11276, 'Ezra 4:4', 'Ezra', 4, 4, '&nbsp;او چې کوم خلق په هغه مُلک کښې اوسېدل نو هغوئ دا کوشش کولو چې يهوديان بې‌حوصلې کړى او د مالِک خُدائ د کور جوړولو نه يې ويروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11277, 'Ezra 4:5', 'Ezra', 4, 5, '&nbsp;هغوئ د فارس د حکومت آفسرانو له د دې دپاره رشوت هم ورکولو چې د هغوئ خِلاف کار وکړى. هغوئ د فارس بادشاه خورس په ټوله بادشاهۍ کښې داسې کول او هغوئ د فارس بادشاه داريوس د بادشاهۍ شروع کېدو پورې دا کار نۀ پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11278, 'Ezra 4:6', 'Ezra', 4, 6, '&nbsp;د اخسويرس بادشاه د بادشاهۍ په شروع کښې، د يهوداه او يروشلم خلقو دشمنانو د هغوئ خِلاف يو ليکلے شوے اِلزام راوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11279, 'Ezra 4:7', 'Ezra', 4, 7, '&nbsp;يو ځل بيا د فارس بادشاه ارتخششتا په دوران کښې، بِشلام، مِتردات، طابئيل او د هغوئ ملګرو بادشاه ته يو خط وليکلو. هغه خط په آرامى ژبه کښې ليکلے شوے وو او بيا د بادشاه دپاره ترجمه کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11280, 'Ezra 4:8', 'Ezra', 4, 8, '&nbsp;رحُوم حکمران او د صُوبې منشى شِمسى هم د يروشلم په حقله ارتخششتا بادشاه ته دا خط وليکلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11281, 'Ezra 4:9', 'Ezra', 4, 9, '&nbsp;”د حکمران رحُوم، د صُوبې منشى شِمسى، د هغوئ د ملګرو، قاضيانو او د نورو ټولو آفسرانو نه، کوم چې د عيلام په مُلک کښې د ارک، بابل او د سوسه سړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11282, 'Ezra 4:10', 'Ezra', 4, 10, '&nbsp;د هغه نورو خلقو په شمول کوم چې عظيم او عزتمند اسور‌بنى‌پال د خپلو کورونو نه بوتلل او د سامريه په ښار کښې او د فرات سيند نمرپرېواتۀ طرف ته سامريه کښې په نورو ځايونو کښې يې دېره کړل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11283, 'Ezra 4:11', 'Ezra', 4, 11, '&nbsp;په خط کښې داسې ليکلے شوى وُو، ”د فرات سيند نمرپرېواتۀ په طرف د هغۀ د خِدمتګارانو نه، ارتخششتا بادشاه ته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11284, 'Ezra 4:12', 'Ezra', 4, 12, '&nbsp;بادشاه سلامت، مونږ تا خبرول غواړُو چې هغه يهوديان کوم ستا د نورو علاقو نه راغلى دى هغوئ په يروشلم کښې دېره شوى دى او هغه خراب او سرکشه ښار بيا جوړوى. هغوئ د دېوالونو بيا جوړول شروع کړى دى او ډېر زر به يې تيار کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11285, 'Ezra 4:13', 'Ezra', 4, 13, '&nbsp;بادشاه سلامت، کۀ دا ښار بيا جوړ شى او د دې دېوالونه سر ته ورسيږى، نو خلق به محصُول، جزيه او پېسې ورکول بند کړى او ستا شاهى محصُول به کم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11286, 'Ezra 4:14', 'Ezra', 4, 14, '&nbsp;نو بادشاه سلامت، مونږ ستا وفادار يُو او مونږ نۀ غواړُو چې د بادشاه دې داسې بې‌عزتى وشى، نو دا ځکه مونږ بادشاه له دا خبر ورلېږلے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11287, 'Ezra 4:15', 'Ezra', 4, 15, '&nbsp;چې تۀ دا حُکم ورکړه چې هغه تاريخ دې ولټولے شى کوم چې ستا پلار نيکۀ ليکلے وو. نو بيا به تا ته پته ولګى چې دا ښار همېشه د بغاوت نه ډک وى او د پخوانى وختونو نه دې بادشاهانو او د صُوبو حکمرانانو له تکليف ورکړے دے. د دې په خلقو باندې حکومت کول همېشه مشکل وُو. نو په دې وجه دا ښار تباه شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11288, 'Ezra 4:16', 'Ezra', 4, 16, '&nbsp;نو په دې وجه زمونږ دا يقين دے کۀ دا ښار بيا جوړ شى او د دې دېوالونه مکمل شى، نو بادشاه سلامت، د فرات سيند نمرپرېواتۀ طرف ته صُوبه به ستا د قابو نه بهر شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11289, 'Ezra 4:17', 'Ezra', 4, 17, '&nbsp;نو بادشاه دا جواب ورولېږلو، ”رحُوم حکمران، د صُوبې منشى شِمسى او د هغوئ هغه ملګرو ته چې کوم په سامريه کښې اوسيږى او د فرات سيند نمرپرېواتۀ طرف ټولو خلقو ته، سلامونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11290, 'Ezra 4:18', 'Ezra', 4, 18, '&nbsp;کوم خط چې تاسو رالېږلے دے هغه لوستلے شوے دے او زما په وړاندې ترجمه شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11291, 'Ezra 4:19', 'Ezra', 4, 19, '&nbsp;ما حُکم وکړو چې تفتيش دې وکړے شى او دا خبره معلومه کړے شوې ده چې يروشلم بې‌شکه د پخوا نه د بادشاهانو خِلاف بغاوت کولو او دا د باغيانو او سرکشه خلقو نه ډک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11292, 'Ezra 4:20', 'Ezra', 4, 20, '&nbsp;هلته طاقتورو بادشاهانو بادشاهى کړې ده او د فرات سيند نمرپرېواتۀ طرف ته په ټوله صُوبه يې حکومت کړے دے او جزيه، محصُول او پېسې يې راټولولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11293, 'Ezra 4:21', 'Ezra', 4, 21, '&nbsp;نو په دې وجه تۀ به فرمان جارى کړې چې ترڅو پورې ما بل حُکم نۀ وى درکړے نو هغه خلق دې د ښار په جوړولو باندې کار بند کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11294, 'Ezra 4:22', 'Ezra', 4, 22, '&nbsp;دا کار سمدستى وکړئ چې داسې زما فائدې ته نور تاوان ونۀ رسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11295, 'Ezra 4:23', 'Ezra', 4, 23, '&nbsp;نو څنګه چې د ارتخششتا بادشاه خط رحُوم، شِمسى او د هغوئ ملګرو ته ولوستلے شو، نو هغوئ يروشلم ته تېز لاړل او يهوديان يې دې ته مجبور کړل چې د ښار بيا جوړول بند کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11296, 'Ezra 4:24', 'Ezra', 4, 24, '&nbsp;نو د خُدائ پاک په کور باندې کار بند وو او د فارس بادشاه داريوس د بادشاهۍ تر دوېم کال پورې کار ځنډولے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11297, 'Ezra 5:1', 'Ezra', 5, 1, '&nbsp;په هغه وخت کښې دوه پېغمبران حجى او د عدو زوئ زکرياه وُو. هغوئ په يهوداه او يروشلم کښې اوسېدونکو يهوديانو له د بنى اِسرائيلو هغه خُدائ پاک په نوم پېشګوئې ورکوله چې کوم د هغوئ دپاسه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11298, 'Ezra 5:2', 'Ezra', 5, 2, '&nbsp;کله چې د شلتى‌اېل زوئ زرُبابل او د يوصدق زوئ يشوَع د هغوئ پېغام واورېدو، نو هغوئ په يروشلم کښې د خُدائ پاک د کور بيا جوړول شروع کړل او د خُدائ پاک هغه دوه پېغمبران د هغوئ سره وُو او د هغوئ مدد يې کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11299, 'Ezra 5:3', 'Ezra', 5, 3, '&nbsp;نو د نمرپرېواتۀ طرف ته فرات حکمران تتنى، شتربوزنى او د هغوئ ملګرى آفسران سمدستى يروشلم ته راغلل او وې وئيل، ”تا له دا حُکم څوک درکوى چې دا کور بيا جوړ کړه او سر ته يې ورسوه؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11300, 'Ezra 5:4', 'Ezra', 5, 4, '&nbsp;هغوئ د هغه ټولو سړو د نومونو تپوس هم وکړو کومو چې د دې په جوړولو کښې مدد کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');